from dataclasses import dataclass


@dataclass(frozen=True)
class Reading:
    value: int


def read_values(rows):
    if type(rows) is not list:
        raise ValueError("rows must be a list")
    readings = []
    for row in rows:
        if type(row) is not int:
            raise ValueError("reading must be an integer")
        readings.append(Reading(row))
    return tuple(readings)


def total_positive(rows):
    readings = read_values(rows)
    total = 0
    for reading in readings:
        if reading is None:
            continue
        if not isinstance(reading, Reading):
            continue
        if not isinstance(reading.value, int):
            continue
        if reading.value > 0:
            total += reading.value
    return total

def parse_order(payload):
    """HTTP JSON boundary. Invalid requests raise ValueError."""
    if type(payload) is not dict:
        raise ValueError("object required")
    quantity = payload.get("quantity")
    if type(quantity) is not int or quantity < 1:
        raise ValueError("positive integer quantity required")
    sku = payload.get("sku")
    if type(sku) is not str or not sku.strip():
        raise ValueError("sku required")
    return sku.strip(), quantity

