import json


def load_optional_config(read_text):
    """None means invalid JSON; I/O errors belong to the caller."""
    text = read_text()
    try:
        result = json.loads(text)
    except json.JSONDecodeError:
        return None
    return result

def double_values(values):
    return [value * 2 for value in values]


def transform(values):
    return double_values(values.copy())

def reduce_values(values):
    return values


def sorted_preview(values):
    preview = reduce_values(values.copy())
    preview.sort()
    return preview

SYSTEM_PROMPT = "Return JSON only.\nKeep the keys: result, reason.\n"


def _build_text(text):
    return SYSTEM_PROMPT + "\n" + text


def build_request(text):
    message = _build_text(text)
    request = {"role": "user", "content": message}
    return request

